@use '../../../../../../ui/styles/portal-layout' as portal;

@include portal.live-layout;

:host {
    min-height: 0;
    background: var(--mat-sys-surface);
}

.sidebar {
    app-sidebar {
        flex: 1;
        min-height: 0;
        overflow: hidden;
    }
}

.content-container {
    min-width: 0;
    background: var(--mat-sys-surface);
}

.video-player {
    background: #000;

    > app-audio-player,
    > app-vjs-player,
    > app-html-video-player,
    > app-art-player {
        flex: 1;
        min-height: 0;
        display: block;
    }
}

.epg {
    border-top: 1px solid var(--mat-sys-outline-variant);
    background: var(--mat-sys-surface);
}

.epg-content {
    > app-epg-list {
        flex: 1;
        min-height: 0;
    }
}

.channel-number-overlay {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    z-index: 1000;
    pointer-events: none;
}

.channel-number-display {
    min-width: 120px;
    padding: 2rem 3rem;
    border: 2px solid rgba(255, 255, 255, 0.1);
    border-radius: 16px;
    background: rgba(0, 0, 0, 0.85);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
    color: #fff;
    font-family: 'DM Sans', sans-serif;
    font-size: 6rem;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-align: center;
    animation: scaleIn 0.15s ease-out;
}

@keyframes scaleIn {
    from {
        opacity: 0;
        transform: scale(0.8);
    }

    to {
        opacity: 1;
        transform: scale(1);
    }
}

@media only screen and (max-width: 599px) {
    :host {
        flex-direction: column-reverse;
    }

    .sidebar {
        width: 100%;
        min-width: 100%;
        max-width: 100%;
        height: 50vh;
        border-right: none;
        border-top: 1px solid var(--mat-sys-outline-variant);
    }

    .content-container {
        height: 50vh;
    }
}

