    if (window.electron?.updateRemoteControlStatus) {
        window.electron.updateRemoteControlStatus({
            portal: 'm3u',
            isLiveView: true,
            supportsVolume: true,
            volume: this.volume,
            muted: this.volume === 0,
        });
    }
}

shouldShowInlinePlayer(channel: Channel | null | undefined): boolean {
    if (!channel) {
        return false;
    }

    return !this.isExternalPlayer(this.playerSettings.player);
}

private getExternalSessionStateKey(
    session: ExternalPlayerSession | null | undefined
): string | null {
    if (!session) {
        return null;
    }

    return `${session.id}:${session.status}`;
}

private isExternalPlayer(
    player: VideoPlayer | null | undefined
): player is VideoPlayer.MPV | VideoPlayer.VLC {
    return player === VideoPlayer.MPV || player === VideoPlayer.VLC;
}

private isTerminalExternalSession(
    session: ExternalPlayerSession | null | undefined
): boolean {
    return session?.status === 'closed' || session?.status === 'error';

content.text:
I have thoroughly explored the codebase and understand the current architecture, patterns, and design system. Here is the detailed implementation plan.

---

## Implementation Plan: Radio/Audio Player Improvements

### Overview

Five files need changes across two libraries. The work breaks into three independent tracks: (A) audio player component rewrite, (B) host layout logic changes, and (C) SCSS theming. Track B depends on understanding Track A's new inputs, but the file edits themselves are independent.

---

### File 1: `libs/ui/playback/src/lib/audio-player/audio-player.component.ts`

**Goal:** Migrate to signal-based APIs, add channel name, volume persistence, fallback logo, elapsed time counter, and theme-aware rendering.

**Signal migration:**
- Replace `@Input() icon!: string` with `readonly icon = input<string>('')`
- Replace `@Input({ required: true }) url!: string` with `readonly url = input.required<string>()`
- Add new input: `readonly channelName = input<string>('')`
- Replace `@ViewChild('audio', { static: true }) audio!: ElementRef<HTMLAudioElement>` with `readonly audioRef = viewChild.required<ElementRef<HTMLAudioElement>>('audio')`
- Remove `implements OnChanges` and the `ngOnChanges` method. Replace with an `effect()` in the constructor that watches `url()` signal changes and calls `load()` + `play()` on the native audio element.

**Volume persistence:**
- In the constructor, read `localStorage.getItem('volume')` and set the initial volume on the audio element (same pattern as `video-player.component.ts` line 172-175).
- Create a `setVolume(value: number)` method that sets `audio.nativeElement.volume` and writes to `localStorage.setItem('volume', String(value))`. Use this in the template's slider `(valueChange)` and in `mute()`.
- Convert `volume` to a writable signal: `readonly volume = signal(1)`. Initialize from localStorage in constructor. Bind the slider to `volume()` and use `(input)` event to call `setVolume()`.

**Elapsed time counter:**
- Add `readonly elapsedSeconds = signal(0)` and a private `intervalId: ReturnType<typeof setInterval> | null = null`.
- In `play()`, start a 1-second interval that increments `elapsedSeconds`. In `stop()`, clear the interval. Reset to 0 on channel change (in the URL effect).
- Add a `formatTime(seconds: number): string` helper that returns `MM:SS` or `H:MM:SS`.

**Fallback logo:**
- Add a computed signal: `readonly displayIcon = computed(() => this.icon() || null)`. In the template, use `@if (displayIcon())` to show the `<img>`, `@else` show a Material icon `radio` inside a styled container.
- Add `(error)` handler on the `<img>` to set a local `logoError = signal(false)` that triggers the fallback.

**Template restructure (inline template stays inline, it's small enough):**

```
<div id="audio-player">
  <div class="radio-logo">
    @if (displayIcon() && !logoError()) {
      <img [src]="displayIcon()" alt="radio icon" (error)="logoError.set(true)" />
    } @else {
      <mat-icon class="fallback-icon">radio</mat-icon>
    }
  </div>

  <div class="station-info">
    <span class="channel-name">{{ channelName() || 'Radio' }}</span>
    @if (playState() === 'play') {
      <span class="now-playing">Now Playing &bull; {{ formatTime(elapsedSeconds()) }}</span>
    } @else {
      <span class="now-playing">Paused</span>
    }
  </div>

  <audio ...> ... </audio>

  <div class="controls"> ... (same prev/play-pause/next, but use playState() signal) </div>

  <div class="volume-panel">
    @if (playState() === 'play') { <div class="playing"> ... bars ... </div> }
    @if (playState() === 'paused') { <div class="playing"> ... stopped bars ... </div> }
    <mat-slider min="0" max="1" step="0.1">
      <input matSliderThumb [ngModel]="volume()" (ngModelChange)="setVolume($event)" />
    </mat-slider>
    <button mat-icon-button (click)="mute()">
      @if (volume() > 0 && !isMuted()) { <mat-icon>volume_up</mat-icon> }
      @if (volume() === 0 || isMuted()) { <mat-icon>volume_off</mat-icon> }
    </button>
  </div>
</div>
```

**Convert `playState` to a signal:** `readonly playState = signal<'play' | 'paused'>('paused')`. Update `play()` and `stop()` to use `.set()`.

**Lifecycle:** Implement `OnDestroy` to clear the elapsed-time interval.

**Estimated final size:** ~160-180 lines, well under the 300-line limit.

---

### File 2: `libs/ui/playback/src/lib/audio-player/audio-player.component.scss`

**Goal:** Theme-aware colors, improved layout with station info, fallback icon styling.

**Key changes:**

1. **Playing bars** -- replace hardcoded `background: white` with `background: var(--app-selection-color, var(--mat-sys-primary))`. This uses the accent color from the theme with a fallback.

2. **`playing-bar-stopped`** -- use `background: var(--mat-sys-on-surface-variant)` for a muted appearance when paused.

3. **New `.station-info` block:**
   ```scss
   .station-info {
     display: flex;
     flex-direction: column;
     align-items: center;
     gap: 4px;
     margin-top: 8px;
   }

   .channel-name {
     font-family: 'DM Sans', sans-serif;
     font-size: 1.25rem;
     font-weight: 600;
     color: var(--mat-sys-on-surface);
     text-align: center;
     max-width: 300px;
     overflow: hidden;
     text-overflow: ellipsis;
     white-space: nowrap;
   }

   .now-playing {
     font-size: 0.85rem;
     color: var(--mat-sys-on-surface-variant);
     letter-spacing: 0.02em;
   }
   ```

4. **Fallback icon styling:**
   ```scss
   .fallback-icon {
     font-size: 96px;
     width: 96px;
     height: 96px;
     color: var(--mat-sys-on-surface-variant);
   }
   ```

5. **Radio logo container** -- add `background: var(--mat-sys-surface-container)` and `border-radius: 14px` (already has border-radius, add the background for the fallback case). Add `overflow: hidden` for image clipping.

6. **`:host`** -- keep `display: flex; justify-content: center;` but change `margin: 20px 0` to `padding: 24px 0` and add `align-items: center; height: 100%;` so when the audio player gets the full content area (EPG hidden), it centers vertically.

---

### File 3: `libs/playlist/m3u/feature-player/src/lib/video-player/video-player.component.html`

**Goal:** Hide EPG for radio channels, pass channel name to audio player, always show inline player for radio.

**Changes at line 30:** Modify the conditional so radio channels always show the inline player regardless of external player setting:

```html
@if (activeChannel.radio === 'true' || shouldShowInlinePlayer(activeChannel)) {
```

This ensures radio channels ALWAYS render the inline audio player block, even when MPV/VLC is the selected player.

**Changes at line 33-35:** Pass channel name to the audio player:

```html
<app-audio-player
    [url]="activeChannel.url"
    [icon]="activeChannel?.tvg?.logo!"
    [channelName]="activeChannel.name || activeChannel?.tvg?.name || ''"
/>
