:host {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100%;
    padding: 24px 0;
}

#audio-player {
    display: flex;
    flex-direction: column;
    gap: 10px;
    align-items: center;
}

.radio-logo {
    border-radius: 14px;
    height: 300px;
    width: 300px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--mat-sys-surface-container);
    overflow: hidden;

    img {
        max-width: 300px;
        max-height: 300px;
    }
}

.fallback-icon {
    font-size: 96px;
    width: 96px;
    height: 96px;
    color: var(--mat-sys-on-surface-variant);
}

.station-info {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    margin-top: 8px;
}

.channel-name {
    font-family: 'DM Sans', sans-serif;
    font-size: 1.25rem;
    font-weight: 600;
    color: var(--mat-sys-on-surface);
    text-align: center;
    max-width: 300px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.now-playing {
    font-size: 0.85rem;
    color: var(--mat-sys-on-surface-variant);
    letter-spacing: 0.02em;
}

.volume-panel {
    display: flex;
    align-self: center;
    align-items: center;

    input {
        flex: 1;
    }
}

.controls {
    height: 100px;
    align-items: center;
    display: flex;
    gap: 8px;
    justify-content: center;
}

.playing {
    width: 36px;
    height: 36px;
    border-radius: 0.3rem;
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    padding: 0.5rem;
    box-sizing: border-box;
}

.playing-bar {
    display: inline-block;
    background: var(--app-selection-color, var(--mat-sys-primary));
    width: 30%;
    height: 100%;
    animation: up-and-down 1.3s ease infinite alternate;
}

.playing-bar-stopped {
    display: inline-block;
    background: var(--mat-sys-on-surface-variant);
    width: 30%;
    height: 100%;
}

.playing-bar1 {
    height: 60%;
}

.playing-bar2 {
    height: 30%;
    animation-delay: -2.2s;
}

.playing-bar3 {
    height: 75%;
    animation-delay: -3.7s;
}

@keyframes up-and-down {
    10% {
        height: 30%;
    }

    30% {
        height: 100%;
    }

    60% {
        height: 50%;
    }

    80% {
        height: 75%;
    }

    100% {
        height: 60%;
    }
}

.icon-button-large {
    transform: scale(2);
    margin: 0 20px;
}

@media only screen and (max-width: 599px) {
    .radio-logo {
        height: 200px;
        width: 200px;

        img {
            max-width: 200px;
            max-height: 200px;
        }
    }
}

