import {
    Component,
    DestroyRef,
    ElementRef,
    computed,
    effect,
    inject,
    input,
    signal,
    viewChild,
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatSliderModule } from '@angular/material/slider';
import { Store } from '@ngrx/store';
import { ChannelActions } from 'm3u-state';

@Component({
    selector: 'app-audio-player',
    template: `
        <div id="audio-player">
            <div class="radio-logo">
                @if (displayIcon() && !logoError()) {
                    <img
                        [src]="displayIcon()"
                        alt="radio icon"
                        (error)="logoError.set(true)"
                    />
                } @else {
                    <mat-icon class="fallback-icon">radio</mat-icon>
                }
            </div>

            <div class="station-info">
                <span class="channel-name">{{
                    channelName() || 'Radio'
                }}</span>
                @if (playState() === 'play') {
                    <span class="now-playing"
                        >Now Playing &bull;
                        {{ formatTime(elapsedSeconds()) }}</span
                    >
                } @else {
                    <span class="now-playing">Paused</span>
                }
            </div>

            <audio preload="metadata" autoplay #audio>
                <source [src]="url()" />
            </audio>

            <div class="controls">
                <button mat-icon-button (click)="switchChannel('previous')">
                    <mat-icon>skip_previous</mat-icon>
                </button>

                @if (playState() === 'paused') {
                    <button
                        class="icon-button-large"
                        mat-icon-button
                        (click)="play()"
                    >
                        <mat-icon>play_arrow</mat-icon>
                    </button>
                }
                @if (playState() === 'play') {
                    <button
                        class="icon-button-large"
                        mat-icon-button
                        (click)="stop()"
                    >
                        <mat-icon>pause</mat-icon>
                    </button>
                }

                <button mat-icon-button (click)="switchChannel('next')">
                    <mat-icon>skip_next</mat-icon>
                </button>
            </div>

            <div class="volume-panel">
                @if (playState() === 'play') {
                    <div class="playing">
                        <span class="playing-bar playing-bar1"></span>
                        <span class="playing-bar playing-bar2"></span>
                        <span class="playing-bar playing-bar3"></span>
                    </div>
                }
                @if (playState() === 'paused') {
                    <div class="playing">
                        <span
                            class="playing-bar-stopped playing-bar1"
                        ></span>
                        <span
                            class="playing-bar-stopped playing-bar2"
                        ></span>
                        <span
                            class="playing-bar-stopped playing-bar3"
                        ></span>
                    </div>
                }
                <mat-slider min="0" max="1" step="0.1" color="accent">
                    <input
                        matSliderThumb
                        [ngModel]="volume()"
                        (ngModelChange)="setVolume($event)"
                    />
                </mat-slider>
                <button mat-icon-button (click)="mute()">
                    @if (volume() > 0 && !isMuted()) {
                        <mat-icon>volume_up</mat-icon>
                    }
                    @if (volume() === 0 || isMuted()) {
                        <mat-icon>volume_off</mat-icon>
                    }
                </button>
            </div>
        </div>
    `,
    styleUrls: ['./audio-player.component.scss'],
    imports: [MatSliderModule, MatIconModule, MatButtonModule, FormsModule],
})
export class AudioPlayerComponent {
    readonly icon = input<string>('');
    readonly url = input.required<string>();
    readonly channelName = input<string>('');

    readonly playState = signal<'play' | 'paused'>('paused');
    readonly volume = signal(1);
    readonly isMuted = signal(false);
    readonly elapsedSeconds = signal(0);
    readonly logoError = signal(false);

    readonly displayIcon = computed(() => this.icon() || null);

    readonly audioRef =
        viewChild.required<ElementRef<HTMLAudioElement>>('audio');

    private store = inject(Store);
    private destroyRef = inject(DestroyRef);
    private fallbackVolume = 1;
    private elapsedInterval: ReturnType<typeof setInterval> | null = null;

    constructor() {
        const saved = parseFloat(localStorage.getItem('volume') ?? '1');
        if (!isNaN(saved)) {
            this.volume.set(Math.max(0, Math.min(1, saved)));
        }

        effect(() => {
            const url = this.url();
            const audio = this.audioRef()?.nativeElement;
            if (!audio || !url) return;
            audio.src = url;
            audio.volume = this.volume();
            audio.load();
            this.logoError.set(false);
            this.elapsedSeconds.set(0);
            this.play();
        });

        this.destroyRef.onDestroy(() => this.clearElapsedInterval());
    }

    play() {
        const audio = this.audioRef()?.nativeElement;
        if (!audio) return;
        const playPromise = audio.play();
        if (playPromise !== undefined) {
            playPromise.catch((error) => console.log(error));
        }
        this.playState.set('play');
        this.startElapsedInterval();
    }

    stop() {
        this.audioRef()?.nativeElement?.pause();
        this.playState.set('paused');
        this.clearElapsedInterval();
    }

    setVolume(value: number) {
        const clamped = Math.max(0, Math.min(1, value));
        this.volume.set(clamped);
        const audio = this.audioRef()?.nativeElement;
        if (audio) audio.volume = clamped;
        localStorage.setItem('volume', String(clamped));
    }

    mute() {
        const audio = this.audioRef()?.nativeElement;
        if (!audio) return;
        audio.muted = !audio.muted;
        this.isMuted.set(audio.muted);
        if (audio.muted) {
            this.fallbackVolume = this.volume();
            this.setVolume(0);
        } else {
            this.setVolume(this.fallbackVolume);
        }
    }

    switchChannel(direction: 'next' | 'previous') {
        this.store.dispatch(
            ChannelActions.setAdjacentChannelAsActive({ direction })
        );
    }

    formatTime(totalSeconds: number): string {
        const h = Math.floor(totalSeconds / 3600);
        const m = Math.floor((totalSeconds % 3600) / 60);
        const s = totalSeconds % 60;
        const mm = String(m).padStart(2, '0');
        const ss = String(s).padStart(2, '0');
        return h > 0 ? `${h}:${mm}:${ss}` : `${mm}:${ss}`;
    }

    private startElapsedInterval() {
        this.clearElapsedInterval();
        this.elapsedInterval = setInterval(
            () => this.elapsedSeconds.update((s) => s + 1),
            1000
        );
    }

    private clearElapsedInterval() {
        if (this.elapsedInterval) {
            clearInterval(this.elapsedInterval);
            this.elapsedInterval = null;
        }
    }
}

