// ─── Host ────────────────────────────────────────────────────────────────────
:host {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    padding: 32px 24px;
    box-sizing: border-box;
    overflow: hidden;
}

// ─── Stage (vertical rhythm) ─────────────────────────────────────────────────
.player-stage {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 28px;
    max-width: 340px;
    width: 100%;
    animation: fadeUp 0.4s ease-out both;
}

// ─── Artwork ─────────────────────────────────────────────────────────────────
.artwork {
    position: relative;
    width: 240px;
    height: 240px;
    border-radius: 20px;
    overflow: hidden;
    background: var(--mat-sys-surface-container);
    box-shadow:
        0 4px 24px rgba(0, 0, 0, 0.12),
        0 1px 4px rgba(0, 0, 0, 0.08);
    transition: box-shadow 0.35s ease;

    &.is-playing {
        box-shadow:
            0 8px 40px rgba(0, 0, 0, 0.18),
            0 2px 8px rgba(0, 0, 0, 0.1),
            0 0 0 1px var(--app-selection-surface);
    }

    img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
    }
}

.artwork-fallback {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(
        145deg,
        var(--mat-sys-surface-container) 0%,
        var(--app-selection-surface) 100%
    );

    mat-icon {
        font-size: 72px;
        width: 72px;
        height: 72px;
        color: var(--app-selection-color, var(--mat-sys-primary));
        opacity: 0.6;
    }
}

// ─── Visualizer (replaces old playing-bars) ──────────────────────────────────
.visualizer {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 32px;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    gap: 3px;
    padding: 0 0 6px;
    background: linear-gradient(transparent, rgba(0, 0, 0, 0.45));
}

.viz-bar {
    width: 3px;
    border-radius: 2px;
    background: var(--app-selection-color, var(--mat-sys-primary));
    animation: viz 1.1s ease-in-out infinite alternate;

    &:nth-child(1) { height: 40%; animation-delay: 0s; }
    &:nth-child(2) { height: 70%; animation-delay: -0.4s; }
    &:nth-child(3) { height: 55%; animation-delay: -0.8s; }
    &:nth-child(4) { height: 80%; animation-delay: -0.3s; }
    &:nth-child(5) { height: 35%; animation-delay: -0.7s; }
}

@keyframes viz {
    0%   { height: 20%; }
    25%  { height: 80%; }
    50%  { height: 45%; }
    75%  { height: 95%; }
    100% { height: 30%; }
}

// ─── Station Meta ────────────────────────────────────────────────────────────
.meta {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    text-align: center;
    padding: 0 8px;
}

.station-name {
    margin: 0;
    font-family: 'DM Sans', sans-serif;
    font-size: 1.35rem;
    font-weight: 700;
    letter-spacing: -0.01em;
    line-height: 1.25;
    color: var(--mat-sys-on-surface);
    max-width: 320px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.station-status {
    font-family: 'DM Sans', sans-serif;
    font-size: 0.7rem;
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--app-selection-color, var(--mat-sys-primary));
    opacity: 0.85;
}

// ─── Transport Controls ──────────────────────────────────────────────────────
.transport {
    display: flex;
    align-items: center;
    gap: 20px;

    button[mat-icon-button] {
        color: var(--mat-sys-on-surface-variant);
        transition: color 0.15s ease;

        &:hover {
            color: var(--mat-sys-on-surface);
        }

        mat-icon {
            font-size: 28px;
            width: 28px;
            height: 28px;
        }
    }
}

.play-btn {
    --mdc-fab-container-color: var(--app-selection-color, var(--mat-sys-primary));
    --mdc-fab-icon-color: #fff;
    --mat-fab-foreground-color: #fff;

    mat-icon {
        font-size: 32px;
        width: 32px;
        height: 32px;
    }
}

// ─── Volume Row ──────────────────────────────────────────────────────────────
.volume-row {
    display: flex;
    align-items: center;
    gap: 4px;
    width: 220px;
}

.vol-btn {
    flex-shrink: 0;
    color: var(--mat-sys-on-surface-variant);
    transform: scale(0.85);

    mat-icon {
        font-size: 20px;
        width: 20px;
        height: 20px;
    }
}

.vol-slider {
    flex: 1;
    --mdc-slider-active-track-color: var(--app-selection-color, var(--mat-sys-primary));
    --mdc-slider-handle-color: var(--app-selection-color, var(--mat-sys-primary));
    --mdc-slider-inactive-track-color: var(--mat-sys-outline-variant);
    --mdc-slider-handle-width: 14px;
    --mdc-slider-handle-height: 14px;
}

// ─── Entrance ────────────────────────────────────────────────────────────────
@keyframes fadeUp {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

// ─── Responsive ──────────────────────────────────────────────────────────────
@media only screen and (max-width: 599px) {
    .artwork {
        width: 180px;
        height: 180px;
        border-radius: 16px;
    }

    .player-stage {
        gap: 20px;
    }

    .station-name {
        font-size: 1.15rem;
    }
}

@media only screen and (max-height: 500px) {
    .artwork {
        width: 140px;
        height: 140px;
    }

    .player-stage {
        gap: 16px;
    }
}

