    &:nth-child(2) { height: 70%; animation-delay: -0.4s; }
    &:nth-child(3) { height: 55%; animation-delay: -0.8s; }
    &:nth-child(4) { height: 80%; animation-delay: -0.3s; }
    &:nth-child(5) { height: 35%; animation-delay: -0.7s; }
}

@keyframes viz {
    0%   { height: 20%; }
    25%  { height: 80%; }
    50%  { height: 45%; }
    75%  { height: 95%; }
    100% { height: 30%; }
}

// ─── Station Meta ────────────────────────────────────────────────────────────
.meta {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    text-align: center;
    padding: 0 8px;
}

.station-name {
    margin: 0;
    font-family: 'DM Sans', sans-serif;
    font-size: 1.35rem;
    font-weight: 700;
    letter-spacing: -0.01em;
    line-height: 1.25;
    color: var(--mat-sys-on-surface);
    max-width: 320px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.station-status {
    font-family: 'DM Sans', sans-serif;
    font-size: 0.7rem;
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--app-selection-color, var(--mat-sys-primary));
    opacity: 0.85;
}

// ─── Transport Controls ──────────────────────────────────────────────────────
.transport {
    display: flex;
    align-items: center;
    gap: 20px;

    button[mat-icon-button] {
        color: var(--mat-sys-on-surface-variant);
        transition: color 0.15s ease;

        &:hover {
            color: var(--mat-sys-on-surface);
        }

        mat-icon {
            font-size: 28px;
            width: 28px;
            height: 28px;
        }
    }
}

.play-btn {
    --mdc-fab-container-color: var(--app-selection-color, var(--mat-sys-primary));
    --mdc-fab-icon-color: #fff;
    --mat-fab-foreground-color: #fff;

    mat-icon {
        font-size: 32px;
        width: 32px;
        height: 32px;
    }
}

// ─── Volume Row ──────────────────────────────────────────────────────────────
.volume-row {
    display: flex;
    align-items: center;
    gap: 4px;
    width: 220px;
}

.vol-btn {
    flex-shrink: 0;
    color: var(--mat-sys-on-surface-variant);
    transform: scale(0.85);

    mat-icon {
        font-size: 20px;
        width: 20px;
        height: 20px;
    }
}

.vol-slider {
    flex: 1;
    --mdc-slider-active-track-color: var(--app-selection-color, var(--mat-sys-primary));
    --mdc-slider-handle-color: var(--app-selection-color, var(--mat-sys-primary));
    --mdc-slider-inactive-track-color: var(--mat-sys-outline-variant);
    --mdc-slider-handle-width: 14px;
    --mdc-slider-handle-height: 14px;
}

// ─── Entrance ────────────────────────────────────────────────────────────────
@keyframes fadeUp {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

// ─── Responsive ──────────────────────────────────────────────────────────────
@media only screen and (max-width: 599px) {
    .artwork {
        width: 180px;
        height: 180px;
        border-radius: 16px;
    }

    .player-stage {
        gap: 20px;
    }

    .station-name {
        font-size: 1.15rem;
    }
}

@media only screen and (max-height: 500px) {
    .artwork {
        width: 140px;
        height: 140px;
    }

    .player-stage {
        gap: 16px;
    }
}

