1	// ============================================================================
2	// Netflix-style Detail View - Cinematic Streaming Design
3	// ============================================================================
4	
5	:host {
6	    --poster-width: 220px;
7	    --poster-shadow: 0 8px 40px rgba(0, 0, 0, 0.15);
8	    --content-max-width: 1400px;
9	
10	    // Light theme colors (default - no .dark-theme class on body)
11	    --hero-gradient-start: rgba(255, 250, 245, 0);
12	    --hero-gradient-mid: rgba(255, 250, 245, 0.75);
13	    --hero-gradient-end: rgba(255, 250, 245, 1);
14	    --surface-bg: #fffaf5;
15	    --text-primary: #1a1a1a;
16	    --text-secondary: rgba(26, 26, 26, 0.75);
17	    --text-muted: rgba(26, 26, 26, 0.5);
18	    --accent-color: #b81d24;
19	    --tag-bg: rgba(0, 0, 0, 0.06);
20	    --tag-border: rgba(0, 0, 0, 0.12);
21	
22	    width: 100%;
23	    height: 100%;
24	    display: block;
25	    overflow: hidden;
26	    background: var(--surface-bg);
27	    color: var(--text-primary);
28	}
29	
30	// Dark theme overrides - cinematic dark mode
31	:host-context(.dark-theme) {
32	    --hero-gradient-start: rgba(20, 20, 20, 0);
33	    --hero-gradient-mid: rgba(20, 20, 20, 0.7);
34	    --hero-gradient-end: rgba(20, 20, 20, 1);
35	    --surface-bg: #141414;
36	    --text-primary: #fff;
37	    --text-secondary: rgba(255, 255, 255, 0.7);
38	    --text-muted: rgba(255, 255, 255, 0.5);
39	    --accent-color: #e50914;
40	    --tag-bg: rgba(255, 255, 255, 0.1);
41	    --tag-border: rgba(255, 255, 255, 0.2);
42	    --poster-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
43	}
44	
45	// ============================================================================
46	// Hero Section - Full container with backdrop
47	// ============================================================================
48	
49	.hero {
50	    position: relative;
51	    width: 100%;
52	    height: 100%;
53	    overflow: hidden;
54	    background: var(
55	        --surface-bg
56	    ); // Solid background prevents any bleed-through
57	
58	    // Floating back button over backdrop
59	    &__back-button {
60	        position: absolute;
61	        top: 16px;
62	        left: 16px;
63	        z-index: 10;
64	        display: flex;
65	        align-items: center;
66	        justify-content: center;
67	        width: 40px;
68	        height: 40px;
69	        border-radius: 50%;
70	        background: rgba(0, 0, 0, 0.5);
71	        backdrop-filter: blur(8px);
72	        border: none;
73	        cursor: pointer;
74	        transition: all 0.2s ease;
75	        color: #fff;
76	
77	        &:hover {
78	            background: rgba(0, 0, 0, 0.7);
79	            transform: scale(1.05);
80	        }
81	
82	        mat-icon {
83	            font-size: 24px;
84	            width: 24px;
85	            height: 24px;
86	        }
87	    }
88	
89	    // Backdrop image layer - fixed at top, never repeats
90	    &__backdrop {
91	        position: absolute;
92	        top: 0;
93	        left: 0;
94	        right: 0;
95	        bottom: auto; // Only use height, not bottom
96	        height: 60%;
97	        background-size: cover;
98	        background-position: center 20%;
99	        background-repeat: no-repeat;
100	        z-index: 0;
101	        overflow: hidden;
102	
103	        // Fallback blur effect when using poster as backdrop
104	        &--blurred {
105	            filter: blur(40px) saturate(1.3);
106	            transform: scale(1.4);
107	            height: 65%;
108	        }
109	    }
110	
111	    // Gradient overlays for text legibility
112	    &__vignette {
113	        position: absolute;
114	        top: 0;
115	        left: 0;
116	        right: 0;
117	        bottom: 0; // Full height to cover everything
118	        z-index: 1;
119	        pointer-events: none;
120	        background: linear-gradient(
121	            to bottom,
122	            transparent 0%,
123	            transparent 35%,
124	            var(--surface-bg) 55%,
125	            var(--surface-bg) 100%
126	        );
127	
128	        // Top area gradient for text legibility over backdrop
129	        &::before {
130	            content: '';
131	            position: absolute;
132	            top: 0;
133	            left: 0;
134	            right: 0;
135	            height: 60%;
136	            background: linear-gradient(
137	                to top,
138	                var(--hero-gradient-end) 0%,
139	                var(--hero-gradient-mid) 50%,
140	                var(--hero-gradient-start) 100%
141	            );
142	        }
143	
144	        // Side fade for poster area
145	        &::after {
146	            content: '';
147	            position: absolute;
148	            top: 0;
149	            left: 0;
150	            height: 50%;
151	            width: 40%;
152	            background: linear-gradient(
153	                to right,
154	                var(--hero-gradient-mid) 0%,
155	                var(--hero-gradient-start) 100%
156	            );
157	        }
158	    }
159	
160	    // Scrollable content area
161	    &__content {
162	        position: absolute;
163	        inset: 0;
164	        z-index: 2;
165	        display: flex;
166	        gap: 32px;
167	        align-items: flex-start;
168	        padding: 140px 40px 60px;
169	        max-width: var(--content-max-width);
170	        margin: 0 auto;
171	        overflow-y: auto;
172	        overflow-x: hidden;
173	        box-sizing: border-box;
174	
175	        // Hide scrollbar but keep functionality
176	        scrollbar-width: none;
177	        -ms-overflow-style: none;
178	        &::-webkit-scrollbar {
179	            display: none;
180	        }
181	    }
182	
183	    // Error state
184	    &__error {
185	        flex-direction: column;
186	        align-items: center;
187	        justify-content: center;
188	        text-align: center;
189	        gap: 16px;
190	
191	        .error-icon {
192	            font-size: 64px;
193	            width: 64px;
194	            height: 64px;
195	            color: var(--text-muted);
196	        }
197	
198	        .error-title {
199	            font-size: 1.25rem;
200	            font-weight: 500;
201	            color: var(--text-secondary);
202	            margin: 0;
203	        }
204	    }
205	}
206	
207	// ============================================================================
208	// Poster Card - Floating with shadow
209	// ============================================================================
210	
211	.poster {
212	    flex-shrink: 0;
213	    width: var(--poster-width);
214	    align-self: flex-start;
215	
216	    &:hover .poster__image {
217	        transform: scale(1.02);
218	    }
219	
220	    &__image {
221	        width: 100%;
222	        aspect-ratio: 2 / 3;
223	        object-fit: cover;
224	        border-radius: 8px;
225	        box-shadow: var(--poster-shadow);
226	        background: linear-gradient(135deg, #2a2a2a 0%, #1a1a1a 100%);
227	        transition: transform 0.3s ease;
228	    }
229	
230	    &__placeholder {
231	        width: 100%;
232	        aspect-ratio: 2 / 3;
233	        border-radius: 8px;
234	        background: linear-gradient(135deg, #3a3a3a 0%, #2a2a2a 100%);
235	        display: flex;
236	        flex-direction: column;
237	        align-items: center;
238	        justify-content: center;
239	        color: rgba(255, 255, 255, 0.8);
240	        box-shadow: var(--poster-shadow);
241	        overflow: hidden;
242	
243	        &-icon {
244	            font-size: 48px;
245	            width: 48px;
246	            height: 48px;
247	            opacity: 0.5;
248	            margin-bottom: 12px;
249	        }
250	
251	        &-text {
252	            font-size: 1rem;
253	            font-weight: 500;
254	            text-align: center;
255	            display: -webkit-box;
256	            -webkit-line-clamp: 4;
257	            -webkit-box-orient: vertical;
258	            overflow: hidden;
259	            overflow-wrap: anywhere;
260	            padding: 16px;
261	        }
262	    }
263	}
264	
265	// ============================================================================
266	// Details Section - Title, metadata, description
267	// ============================================================================
268	
269	.details {
270	    flex: 1;
271	    min-width: 0;
272	    padding-bottom: 24px;
273	
274	    &__title {
275	        font-size: clamp(1.75rem, 4vw, 3rem);
276	        font-weight: 700;
277	        line-height: 1.1;
278	        margin: 0 0 16px 0;
279	        letter-spacing: -0.02em;
280	        text-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
281	        overflow-wrap: anywhere;
282	        display: -webkit-box;
283	        -webkit-line-clamp: 3;
284	        -webkit-box-orient: vertical;
285	        overflow: hidden;
286	    }
287	
288	    &__tags {
289	        display: flex;
290	        flex-wrap: wrap;
291	        gap: 8px;
292	        margin-bottom: 16px;
293	    }
294	
295	    // These styles are for Projected Content, we need to ensure they apply
296	    // using ::ng-deep or just assume the global styles will handle them?
297	    // Actually, since we project content, the styles defined here might NOT apply to the projected content
298	    // unless we use ::ng-deep or the content itself has these styles.
299	    // However, since we are moving the "shell", the container classes (.details__tags) are here.
300	    // The inner items (.details__tag) will be in the projected content.
301	    // So we need ::ng-deep here for .details__tag.
302	
303	    ::ng-deep .details__tag {
304	        display: inline-flex;
305	        align-items: center;
306	        gap: 4px;
307	        padding: 4px 12px;
308	        font-size: 0.8125rem;
309	        font-weight: 500;
310	        background: var(--tag-bg);
311	        border: 1px solid var(--tag-border);
312	        border-radius: 4px;
313	        backdrop-filter: blur(8px);
314	
315	        &--rating {
316	            color: #ffd700;
317	            border-color: rgba(255, 215, 0, 0.3);
318	        }
319	    }
