// ─── Radio Player — cinematic hero layout ────────────────────────────────────
// Mirrors the content-hero/vod-details pattern: blurred backdrop, vignette,
// floating artwork + controls centred in the available space.

:host {
    display: block;
    width: 100%;
    height: 100%;
    overflow: hidden;
}

// ─── Hero container ──────────────────────────────────────────────────────────
.radio-hero {
    position: relative;
    width: 100%;
    height: 100%;
    overflow: hidden;
    background: var(--mat-sys-surface);
}

// ─── Blurred backdrop (station logo, blown up) ──────────────────────────────
.backdrop {
    position: absolute;
    inset: 0;
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    filter: blur(60px) saturate(1.4) brightness(0.7);
    transform: scale(1.6);
    opacity: 0.55;
    z-index: 0;
}

// ─── Vignette overlay (matches content-hero pattern) ─────────────────────────
.vignette {
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    background:
        radial-gradient(
            ellipse 80% 70% at 50% 40%,
            transparent 0%,
            var(--mat-sys-surface) 100%
        );

    &::after {
        content: '';
        position: absolute;
        inset: 0;
        background: linear-gradient(
            to bottom,
            transparent 0%,
            color-mix(in srgb, var(--mat-sys-surface) 40%, transparent) 50%,
            var(--mat-sys-surface) 85%
        );
    }
}

// ─── Floating content stage ──────────────────────────────────────────────────
.stage {
    position: relative;
    z-index: 2;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100%;
    gap: 20px;
    padding: 32px 24px;
    box-sizing: border-box;
    animation: fadeUp 0.5s ease-out both;
}

// ─── Artwork card ────────────────────────────────────────────────────────────
.artwork {
    width: 200px;
    height: 200px;
    border-radius: 18px;
    overflow: hidden;
    background: var(--mat-sys-surface-container);
    box-shadow:
        0 8px 40px rgba(0, 0, 0, 0.22),
        0 2px 8px rgba(0, 0, 0, 0.12);
    transition: box-shadow 0.4s ease, transform 0.4s ease;
    flex-shrink: 0;

    &.is-playing {
        animation: artwork-pulse 3s ease-in-out infinite;
        transform: translateY(-2px);
    }

    img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
    }
}

.artwork-fallback {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(
        145deg,
        var(--mat-sys-surface-container) 0%,
        var(--app-selection-surface) 100%
    );

    mat-icon {
        font-size: 64px;
        width: 64px;
        height: 64px;
        color: var(--app-selection-color, var(--mat-sys-primary));
        opacity: 0.5;
    }
}

// ─── Station name ────────────────────────────────────────────────────────────
.station-name {
    margin: 4px 0 0;
    font-family: 'DM Sans', sans-serif;
    font-size: clamp(1.15rem, 2.5vw, 1.5rem);
    font-weight: 700;
    letter-spacing: -0.015em;
    line-height: 1.2;
    color: var(--mat-sys-on-surface);
    text-align: center;
    max-width: 380px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    text-shadow: 0 1px 6px rgba(0, 0, 0, 0.15);
}

// ─── Live / Paused badge ─────────────────────────────────────────────────────
.station-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-family: 'DM Sans', sans-serif;
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: var(--mat-sys-on-surface-variant);
    padding: 3px 12px;
    border-radius: 999px;
    border: 1px solid var(--mat-sys-outline-variant);
    background: color-mix(in srgb, var(--mat-sys-surface-container) 60%, transparent);
    backdrop-filter: blur(6px);

    &.live {
        color: var(--app-selection-color, var(--mat-sys-primary));
        border-color: var(--app-selection-border);
        background: var(--app-selection-surface);
    }
}

.pulse {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: currentColor;
    animation: pulse-ring 1.8s ease-in-out infinite;
}

@keyframes pulse-ring {
    0%, 100% { opacity: 1; transform: scale(1); }
    50%      { opacity: 0.5; transform: scale(1.6); }
}

// ─── Transport controls ──────────────────────────────────────────────────────
.transport {
    display: flex;
    align-items: center;
    gap: 24px;
    margin-top: 4px;
}

.skip-btn {
    color: var(--mat-sys-on-surface-variant);
    transition: color 0.15s ease, transform 0.15s ease;

    &:hover {
        color: var(--mat-sys-on-surface);
        transform: scale(1.08);
    }

    mat-icon {
        font-size: 28px;
        width: 28px;
        height: 28px;
    }
}

.play-btn {
    --mdc-fab-container-color: var(--app-selection-color, var(--mat-sys-primary));
    --mdc-fab-icon-color: #fff;
    --mat-fab-foreground-color: #fff;
    transition: transform 0.2s ease, box-shadow 0.2s ease;

    &:hover {
        transform: scale(1.06);
    }

    mat-icon {
        font-size: 32px;
        width: 32px;
        height: 32px;
    }
}

// ─── Volume row ──────────────────────────────────────────────────────────────
.volume-row {
    display: flex;
    align-items: center;
    gap: 2px;
    width: 200px;
    margin-top: 4px;
}

.vol-icon {
    flex-shrink: 0;
    color: var(--mat-sys-on-surface-variant);
    transform: scale(0.8);
}

.vol-slider {
    flex: 1;
    --mdc-slider-active-track-color: var(--app-selection-color, var(--mat-sys-primary));
    --mdc-slider-handle-color: var(--app-selection-color, var(--mat-sys-primary));
    --mdc-slider-inactive-track-color: var(--mat-sys-outline-variant);
    --mdc-slider-handle-width: 12px;
    --mdc-slider-handle-height: 12px;
}

// ─── Entrance ────────────────────────────────────────────────────────────────
@keyframes fadeUp {
    from { opacity: 0; transform: translateY(16px); }
    to   { opacity: 1; transform: translateY(0); }
}

@keyframes artwork-pulse {
    0%, 100% {
        box-shadow:
            0 8px 40px rgba(0, 0, 0, 0.22),
            0 0 0 1px var(--app-selection-surface),
            0 0 32px var(--app-selection-glow);
    }
    50% {
        box-shadow:
            0 12px 56px rgba(0, 0, 0, 0.3),
            0 0 0 1px var(--app-selection-border),
            0 0 64px var(--app-selection-glow);
    }
}

// ─── Responsive ──────────────────────────────────────────────────────────────
@media only screen and (max-width: 599px) {
    .artwork {
        width: 160px;
        height: 160px;
        border-radius: 14px;
    }

    .stage { gap: 16px; padding: 24px 16px; }
    .transport { gap: 18px; }
}

@media only screen and (max-height: 480px) {
    .artwork {
        width: 120px;
        height: 120px;
        border-radius: 12px;
    }

    .stage { gap: 10px; padding: 16px 12px; }
    .station-name { font-size: 1rem; }
}

