// ─── Radio Player — cinematic hero layout ────────────────────────────────────
// Mirrors the content-hero/vod-details pattern: blurred backdrop, vignette,
// floating artwork + controls centred in the available space.

:host {
    display: block;
    width: 100%;
    height: 100%;
    overflow: hidden;
}

// ─── Hero container ──────────────────────────────────────────────────────────
.radio-hero {
    position: relative;
    width: 100%;
    height: 100%;
    overflow: hidden;
    background: var(--mat-sys-surface);
}

// ─── Blurred backdrop (station logo, blown up) ──────────────────────────────
.backdrop {
    position: absolute;
    inset: 0;
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    filter: blur(60px) saturate(1.4) brightness(0.7);
    transform: scale(1.6);
    opacity: 0.55;
    z-index: 0;
}

// ─── Vignette overlay (matches content-hero pattern) ─────────────────────────
.vignette {
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    background:
        radial-gradient(
            ellipse 80% 70% at 50% 40%,
            transparent 0%,
            var(--mat-sys-surface) 100%
        );

    &::after {
        content: '';
        position: absolute;
        inset: 0;
        background: linear-gradient(
            to bottom,
            transparent 0%,
            color-mix(in srgb, var(--mat-sys-surface) 40%, transparent) 50%,
            var(--mat-sys-surface) 85%
        );
    }
}

// ─── Floating content stage ──────────────────────────────────────────────────
.stage {
    position: relative;
    z-index: 2;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100%;
    gap: 20px;
    padding: 32px 24px;
    box-sizing: border-box;
    animation: fadeUp 0.5s ease-out both;
}

// ─── Artwork card ────────────────────────────────────────────────────────────
.artwork {
    max-width: 220px;
    max-height: 220px;
    border-radius: 18px;
    overflow: hidden;
    background: var(--mat-sys-surface-container);
    box-shadow:
        0 8px 40px rgba(0, 0, 0, 0.22),
        0 2px 8px rgba(0, 0, 0, 0.12);
    transition: box-shadow 0.4s ease, transform 0.4s ease;
    flex-shrink: 0;

    &.is-playing {
        animation: artwork-pulse 3s ease-in-out infinite;
        transform: translateY(-2px);
    }

    img {
        display: block;
        max-width: 220px;
        max-height: 220px;
        width: auto;
        height: auto;
    }
}

// Fallback keeps a fixed square since there's no image to dictate size
.artwork-fallback {
    width: 200px;
    height: 200px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(
        145deg,
        var(--mat-sys-surface-container) 0%,
        var(--app-selection-surface) 100%
    );

    mat-icon {
        font-size: 64px;
        width: 64px;
        height: 64px;
        color: var(--app-selection-color, var(--mat-sys-primary));
        opacity: 0.5;
    }
}

// ─── Station name ────────────────────────────────────────────────────────────
